export const MedalIcon = ({ rank = 1, size = 24, className = '' }) => {
  const color = rank === 1 ? '#FFD700' : rank === 2 ? '#C0C0C0' : '#CD7F32';
  const ribbon = rank === 1 ? '#EF4444' : rank === 2 ? '#3B82F6' : '#10B981';
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      className={`reicon reicon-medal ${className}`}
      style={{ display: 'inline-block', verticalAlign: 'middle' }}
    >
      <path d="M7 2L10 9H6L3 2H7Z" fill={ribbon} />
      <path d="M17 2L14 9H18L21 2H17Z" fill={ribbon} />
      <path d="M10 2L12 7L14 2H10Z" fill="rgba(0,0,0,0.15)" />
      <circle cx="12" cy="15" r="7" fill={color} />
      <circle cx="12" cy="15" r="5" fill="none" stroke="rgba(0,0,0,0.2)" strokeWidth="1" />
      <text x="12" y="18" textAnchor="middle" fill="#1E293B" fontSize="8" fontWeight="bold" fontFamily="sans-serif">
        {rank}
      </text>
    </svg>
  );
};

