export const QuestChestIcon = ({
  chestType = 'wood',
  size = 24,
  claimed = false,
  className = ''
}) => {
  if (claimed) {
    return <CheckIcon size={size} color="#10B981" className={className} />;
  }

  if (chestType === 'gold') {
    return <CrownIcon size={size} color="#FBBF24" className={className} />;
  }
  if (chestType === 'cyan') {
    return <GemSparkle size={size} color="#22D3EE" className={className} />;
  }
  return <ArchiveBoxIcon size={size} color="#A78BFA" className={className} />;
};

