export const CourseIcon = ({
  courseId,
  iconKey,
  size = 24,
  color,
  className = ''
}) => {
  const key =
    iconKey ||
    (courseId === 'qc'
      ? 'atom'
      : courseId === 'qp'
      ? 'microscope'
      : courseId === 'qa'
      ? 'math'
      : courseId === 'qpr'
      ? 'laptop-code'
      : 'atom');

  const defaultColor =
    courseId === 'qc'
      ? '#00CD9C'
      : courseId === 'qp'
      ? '#38BDF8'
      : courseId === 'qa'
      ? '#8B5CF6'
      : courseId === 'qpr'
      ? '#F43F5E'
      : '#00CD9C';

  const finalColor = color || defaultColor;

  if (key === 'microscope') return <MicroscopeIcon size={size} color={finalColor} className={className} />;
  if (key === 'laptop-code') return <LaptopCodeIcon size={size} color={finalColor} className={className} />;
  if (key === 'math') return <MathIcon size={size} color={finalColor} className={className} />;
  if (key === 'cpu-bolt') return <CpuBoltIcon size={size} color={finalColor} className={className} />;
  return <AtomIcon size={size} color={finalColor} className={className} />;
};

